        "date": date,
        "interest_rate": interest_rate
    }
```

### 2. Create an Agent with Tools
```py
finance_agent = client.beta.agents.create(
    model="mistral-medium-latest",
    description="Can fetch ECB interest rates and generate plots",
    name="finance-agent",
    tools=[
        {
            "type": "function",
            "function": {
                "name": "get_european_central_bank_interest_rate",
                "description": "Retrieve the real interest rate of the European Central Bank.",
                "parameters": {
                    "type": "object",
                    "properties": {
                        "date": {
                            "type": "string"
                        }
                    },
                    "required": ["date"]
                }
            }
        }
    ]
)
```

### 3. Start a Conversation and Handle Function Calls
```py
response = client.beta.conversations.start(
    agent_id=finance_agent.id,
    inputs="Given the interest rate of the European Central Bank as of jan 2025, plot a graph of the compounded interest rate over the next 10 years"
)

